css:
/* Main Wrapper */
.delivery-note-wrapper {
    font-family: Arial, Helvetica, sans-serif;
    font-size: 11px;
    line-height: 1.3;
    padding: 0;
    margin: 0;
    color: #000;
}

/* Header */
.dn-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 10px 0;
    margin-bottom: 5px;
}

.logo-section {
    flex: 0 0 280px;
}

.company-logo-img {
    max-height: 70px;
    max-width: 250px;
}

.title-section {
    flex: 1;

}

.doc-title {
    font-size: 22px;
    font-weight: bold;
    margin: 0;
    text-decoration: underline;
    letter-spacing: 1px;
}

.dn-divider {
    height: 2px;
    background-color: #000;
    margin-bottom: 10px;
}

/* Main Info Box */
.main-info-box {
    display: flex;
    border: 1px solid #000;
    margin-bottom: 10px;
}

.left-info {
    flex: 1;
    border-right: 1px solid #000;
}

.right-info {
    flex: 1;
}

.info-grid {
    width: 100%;
    border-collapse: collapse;
}

.info-grid tr {
    border-bottom: 1px solid #000;
}

.info-grid tr:last-child {
    border-bottom: none;
}

.label-cell {
    width: 112px;
    padding: 6px 8px;
    font-weight: bold;
    border-right: 1px solid #000;
    vertical-align: top;
    font-size: 11px;
}

.value-cell {
    padding: 6px 10px;
    vertical-align: top;
    font-size: 12px;
}

/* Items Table */
.items-grid {
    width: 100%;
    border-collapse: collapse;
    border: 1px solid #000;
    margin-bottom: 10px;
}

.items-grid th {
    background-color: #f5f5f5;
    border: 1px solid #000;
    padding: 6px 8px;
    font-weight: bold;
    text-align: left;
    font-size: 10px;
}

.items-grid td {
    border: 1px solid #000;
    padding: 6px 8px;
    font-size: 10px;
    vertical-align: top;
}

.text-center {
    text-align: center;
}

/* Package Info Box */
.package-info-box {
    display: flex;
    border: 1px solid #000;
    margin-bottom: 10px;
    min-height: 120px;
}

.pkg-left {
    flex: 0 0 62%;
    border-right: 1px solid #000;
}

.pkg-right {
    flex: 1;
    padding: 10px;
    font-size: 10px;
}

.pkg-grid {
    width: 100%;
    border-collapse: collapse;
}

.pkg-grid tr {
    border-bottom: 1px solid #000;
}

.pkg-grid tr:last-child {
    border-bottom: none;
}

.pkg-label {
    width: 130px;
    padding: 7px 10px;
    border-right: 1px solid #000;
    vertical-align: middle;
    font-size: 12px;
}

.pkg-value {
    padding: 7px 10px;
    vertical-align: middle;
    font-size: 14px;
}

/* Important Note Box */
.important-box {
    border: 1px solid #000;
    padding: 8px 10px;
    margin-bottom: 10px;
}

.important-title {
    font-weight: bold;
    margin-bottom: 4px;
    font-size: 10px;
}

.important-content {
    font-size: 7px;
    line-height: 1.5;
    text-align: justify;
}

/* Signature Box */
.signature-box {
    display: flex;
    border: 1px solid #000;
    min-height: 150px;
    margin-bottom: 8px;
}

.sig-left,
.sig-center,
.sig-right {
    flex: 1;
    padding: 12px 10px;
}

.sig-left {
    border-right: 1px solid #000;
}

.sig-center {
    border-right: 1px solid #000;
    display: flex;
    align-items: center;
    justify-content: center;
}

.sig-line {
    font-weight: bold;
    margin-bottom: 14px;
    font-size: 10px;
}

.stamp-circle {
    width: 90px;
    height: 90px;
    border: 2px solid #000;
    border-radius: 50%;
}

/* Page Number */
.page-num {
    text-align: right;
    font-size: 10px;
    margin-top: 5px;
}

/* Print Styles */
@media print {
    .delivery-note-wrapper {
        padding: 0;
    }

    @page {
        margin: 15mm;
        size: A4;
    }
}
